<template><div><p>休息保留原区间及是否计工时；记录为空不自动声明已核全，不将休息当另一可并行班次。</p><el-button :disabled="disabled||modelValue.length>=256" @click="emit('update:modelValue',[...modelValue,{accounting:{}}])">添加原休息区间</el-button><p>共 {{ modelValue.length }} 段原休息，须按真实时间顺序填写；没有记录不自动声明完整。</p><article v-for="(row,index) in visible" :key="start+index" :aria-label="`原休息区间${start+index+1}`"><el-form-item label="原休息开始UTC"><el-input v-model="row.start_at" aria-label="原休息开始UTC" :disabled="disabled" /></el-form-item><el-form-item label="原休息结束UTC"><el-input v-model="row.end_at" aria-label="原休息结束UTC" :disabled="disabled" /></el-form-item><nullable-value v-model="row.accounting" kind="boolean" label="原休息是否计工时" /><el-button :disabled="disabled" @click="emit('update:modelValue',modelValue.filter((_,i)=>i!==start+index))">移除此未提交休息</el-button></article><el-pagination v-if="modelValue.length>20" v-model:current-page="page" :page-size="20" :total="modelValue.length" layout="prev,pager,next" /></div></template>
<script setup>
import {computed,ref,watch} from 'vue';import NullableValue from './NullableValue.vue';
const props=defineProps({modelValue:{type:Array,default:()=>[]},disabled:{type:Boolean,default:false}}),emit=defineEmits(['update:modelValue']),page=ref(1),start=computed(()=>(page.value-1)*20),visible=computed(()=>props.modelValue.slice(start.value,start.value+20));watch(()=>props.modelValue.length,n=>page.value=Math.min(page.value,Math.max(1,Math.ceil(n/20))));
</script>
<style scoped>article{border:1px solid #ddd;padding:12px;margin:8px 0}</style>
